from pathlib import Path

p=Path('src/import/emblemOcrRefinement.ts')
s=p.read_text()
old="function ambiguousTierGlyph(words:readonly Word[],currentTier:QualityTier):{tierWord:Word;glyphWord:Word}|undefined{if(currentTier!==1)return undefined;for(const tierWord of words.filter(w=>ocrSimilarity(w.text,'TIER')>=.62)){const tierRight=tierWord.left+tierWord.width,tierY=tierWord.top+tierWord.height/2;for(const glyphWord of words){const token=glyphWord.text.toUpperCase().replace(/[^A-Z0-9\\]|]/g,''),confused=token.replace(/[1L|]/g,'I').replace(/]/g,'I'),glyphY=glyphWord.top+glyphWord.height/2,yTolerance=Math.max(tierWord.height,glyphWord.height)*.7,rightGap=glyphWord.left-tierRight,maxGap=Math.max(12,tierWord.height*1.5);if(confused==='I'&&glyphWord.confidence<TIER_GLYPH_RETRY_CONFIDENCE_CEILING&&Math.abs(glyphY-tierY)<=yTolerance&&rightGap>=-2&&rightGap<=maxGap)return{tierWord,glyphWord};}}return undefined;}"
new="function ambiguousTierGlyphEvidence(words:readonly {text:string;confidence:number;x:number;y:number}[]|undefined,currentTier:QualityTier):boolean{if(currentTier!==1||!words?.length)return false;for(const tierWord of words.filter(w=>ocrSimilarity(w.text,'TIER')>=.62)){for(const glyphWord of words){const token=glyphWord.text.toUpperCase().replace(/[^A-Z0-9\\]|]/g,''),confused=token.replace(/[1L|]/g,'I').replace(/]/g,'I'),dx=glyphWord.x-tierWord.x,dy=Math.abs(glyphWord.y-tierWord.y);if(confused==='I'&&glyphWord.confidence<TIER_GLYPH_RETRY_CONFIDENCE_CEILING&&dx>0&&dx<=40&&dy<=6)return true;}}return false;}\nfunction tierAnchorWord(words:readonly Word[]):Word|undefined{return words.filter(w=>ocrSimilarity(w.text,'TIER')>=.62).sort((a,b)=>b.confidence-a.confidence)[0];}"
